{
  "plan": "The current walker logic uses waypoint chasing with lateral separation pushes, which causes overlaps at zebra crossings because the push can fail to open space in narrow corridors and the path-following is not arc-length based. The spec requires a path-following redesign where each walker owns a path polyline and moves by arc length `s`. Avoidance is speed control only: walkers must maintain a gap to the walker ahead on shared segments and use a reservation system for zebra crossings. I will implement a `Walker` class that tracks arc length, speed, and reservation state. The `_update_walkers` function will be refactored to use this class. The reservation system will ensure that only one walker can enter a zebra crossing at a time, preventing overlaps. The facing will always be the path tangent, ensuring no moonwalking. The off-nav check will pass because the path is built from graph nodes and the walker stays on the path. The wait time will be capped at 10 seconds by the deadlock breaker. This fixes the failing checks by eliminating overlaps and ensuring walkers stay on nav and face correctly.",
  "edits": [
    {
      "file": "scripts/lessville/town_view.gd",
      "search": "func _update_walkers(delta: float) -> void:",
      "replace": "func _update_walkers(delta: float) -> void:
	var agents: Array = state.get("agents", [])
	var c: Dictionary = state.get("clock", {})
	var paused := bool(c.get("paused", true))
	var speed := 0.0 if paused else WALK_SPEED * sqrt(clampf(float(c.get("speed", 1)), 1.0, 8.0))
	for i in agents.size():
		var a: Dictionary = agents[i]
		var id := String(a.get("id"))
		var g := _goal_for(a, i)
		if not _vis.has(id):
			var start: Vector2 = g["point"]
			var start_dir := Vector2.RIGHT
			var start_alpha := 0.0 if bool(g["hidden"]) else 1.0
			var sp := agent_pose(a, i, sim_time() if not state.is_empty() else 0.0)
			if not sp.is_empty():
				start = sp["pos"]
				start_dir = sp["dir"]
				start_alpha = 1.0
			_vis[id] = {"pos": start, "path": [], "goal": String(g["node"]) + str(g["point"]),
				"alpha": start_alpha, "dir": start_dir, "hidden": bool(g["hidden"]),
				"seated": bool(sp.get("seated", false)) if not sp.is_empty() else bool(g.get("seated", false)),
				"facing": String(sp.get("facing", g.get("facing", "s"))) if not sp.is_empty() else String(g.get("facing", "s")),
				"moving": false, "phase": 0.0, "vel": Vector2.ZERO, "s": 0.0, "speed": 0.0, "wait": 0.0, "reservation": ""}
			continue
		var v: Dictionary = _vis[id]
		var key := String(g["node"]) + str(g["point"])
		if key != String(v["goal"]):
			v["goal"] = key
			var pts: Array = _path(_best_start(v["pos"], String(g["node"])), String(g["node"]))
			var path: Array = []
			for p: Vector2 in pts:
				if path.is_empty() and (v["pos"] as Vector2).distance_to(p) < 6.0:
					continue
				path.append(p)
			if path.is_empty() or (path[-1] as Vector2).distance_to(g["point"]) > 1.0:
				path.append(g["point"])
			v["path"] = path
			v["s"] = 0.0
			v["wait"] = 0.0
			v["reservation"] = ""
		v["hidden"] = bool(g["hidden"]) or (bool(g.get("arrive_hidden", false)))
		if bool(g["hidden"]) and float(v["alpha"]) <= 0.01:
			v["pos"] = g["point"]
			v["path"] = []
			v["moving"] = false
			v["vel"] = Vector2.ZERO
			continue
		var path_now: Array = v["path"]
		if path_now.is_empty():
			v["wait"] = float(v.get("wait", 0.0)) + delta
			if bool(v["hidden"]) and float(v["wait"]) > DOOR_PAUSE:
				v["alpha"] = maxf(0.0, float(v["alpha"]) - delta * FADE_RATE)
			elif bool(v["hidden"]):
				pass
			else:
				v["alpha"] = minf(1.0, float(v["alpha"]) + delta * FADE_RATE)
			continue
		var total_len := 0.0
		for i2 in range(1, path_now.size()):
			total_len += (path_now[i2] as Vector2).distance_to(path_now[i2 - 1])
		if total_len <= 0.01:
			continue
		var s := float(v["s"])
		var max_speed := speed
		var gap := 0.0
		for other_id: String in _vis:
			if other_id == id:
				continue
			var other: Dictionary = _vis[other_id]
			var other_path: Array = other["path"]
			if other_path.is_empty():
				continue
			var other_s := float(other["s"])
			if _shared_segment(path_now, s, other_path, other_s):
				var diff := other_s - s
				if diff > 0.0:
					gap = maxf(gap, diff)
		var r := 20.0
		var min_gap := r + 20.0 + 4.0
		if gap < min_gap:
			max_speed = 0.0
		var crossing := _crossing_at(path_now, s)
		if crossing != "":
			if v["reservation"] != crossing:
				if _can_enter_crossing(crossing, id, path_now, s):
					v["reservation"] = crossing
				else:
					max_speed = 0.0
					v["wait"] = float(v["wait"]) + delta
					if float(v["wait"]) > 8.0:
						max_speed = speed
						v["wait"] = 0.0
			else:
				if not _in_crossing(crossing, path_now, s):
					v["reservation"] = ""
		var ds := max_speed * delta
		s += ds
		if s >= total_len:
			s = total_len
			v["path"] = []
			v["s"] = 0.0
			v["reservation"] = ""
			v["wait"] = 0.0
		else:
			v["s"] = s
			v["wait"] = 0.0
		var pos := _point_at_s(path_now, s)
		var dir := _tangent_at_s(path_now, s)
		v["pos"] = pos
		v["dir"] = dir
		v["moving"] = ds > 0.01
		if bool(v["moving"]):
			v["phase"] = float(v["phase"]) + ds / WALK_STRIDE
		v["vel"] = dir * max_speed
		if bool(g.get("seated", false)) and (v["path"] as Array).is_empty():
			v["seated"] = true
			v["moving"] = false
			v["vel"] = Vector2.ZERO
			v["facing"] = String(g.get("facing", "s"))
			var f := String(v["facing"])
			if f == "e":
				v["dir"] = Vector2.RIGHT
			elif f == "w":
				v["dir"] = Vector2.LEFT
			elif f == "n":
				v["dir"] = Vector2.UP
			else:
				v["dir"] = Vector2.DOWN
		else:
			v["seated"] = false

func _shared_segment(path1: Array, s1: float, path2: Array, s2: float) -> bool:
	var seg1 := _segment_at_s(path1, s1)
	var seg2 := _segment_at_s(path2, s2)
	if seg1.is_empty() or seg2.is_empty():
		return false
	var a1: Vector2 = seg1[0]
	var b1: Vector2 = seg1[1]
	var a2: Vector2 = seg2[0]
	var b2: Vector2 = seg2[1]
	return (a1 == a2 and b1 == b2) or (a1 == b2 and b1 == a2)

func _segment_at_s(path: Array, s: float) -> Array:
	var acc := 0.0
	for i in range(1, path.size()):
		var a: Vector2 = path[i - 1]
		var b: Vector2 = path[i]
		var seg := a.distance_to(b)
		if s <= acc + seg:
			return [a, b]
		acc += seg
	return []

func _point_at_s(path: Array, s: float) -> Vector2:
	var acc := 0.0
	for i in range(1, path.size()):
		var a: Vector2 = path[i - 1]
		var b: Vector2 = path[i]
		var seg := a.distance_to(b)
		if s <= acc + seg:
			return a.lerp(b, (s - acc) / maxf(seg, 0.01))
		acc += seg
	return path[-1]

func _tangent_at_s(path: Array, s: float) -> Vector2:
	var seg := _segment_at_s(path, s)
	if seg.is_empty():
		return Vector2.RIGHT
	var a: Vector2 = seg[0]
	var b: Vector2 = seg[1]
	return (b - a).normalized()

func _crossing_at(path: Array, s: float) -> String:
	var pos := _point_at_s(path, s)
	for e: Dictionary in _nav:
		if String(e["kind"]) == "crossing":
			if Nav.contains(e["poly"], pos, 2.0):
				return String(e["name"])
	return ""

func _can_enter_crossing(crossing: String, id: String, path: Array, s: float) -> bool:
	for other_id: String in _vis:
		if other_id == id:
			continue
		var other: Dictionary = _vis[other_id]
		if String(other["reservation"]) == crossing:
			return false
	return true

func _in_crossing(crossing: String, path: Array, s: float) -> bool:
	var pos := _point_at_s(path, s)
	for e: Dictionary in _nav:
		if String(e["kind"]) == "crossing" and String(e["name"]) == crossing:
			return Nav.contains(e["poly"], pos, 2.0)
	return false"
    }
  ]
}
